def split_accounts(apps, schema_editor):
    User = apps.get_model('marketplace', 'User')
    LandOwner = apps.get_model('marketplace', 'LandOwner')
    ServiceProvider = apps.get_model('marketplace', 'ServiceProvider')
    AdminAccount = apps.get_model('marketplace', 'AdminAccount')
    Booking = apps.get_model('marketplace', 'Booking')

    admin_map = {}
    for user in User.objects.filter(role='admin'):
        account = AdminAccount.objects.create(
            username=user.username,
            password=user.password,
            name=user.name or '',
            is_active=user.is_active,
            last_login=user.last_login,
            date_joined=user.date_joined,
        )
        admin_map[user.pk] = account.pk

    for user in User.objects.filter(role='farmer'):
        LandOwner.objects.create(
            user_id=user.pk,
            farm_city_id=user.farm_city_id,
            farm_address=user.farm_address or '',
            farm_latitude=user.farm_latitude,
            farm_longitude=user.farm_longitude,
            created_by_id=admin_map.get(user.created_by_id),
        )

    for user in User.objects.filter(role='worker'):
        provider = ServiceProvider.objects.create(
            user_id=user.pk,
            bio=user.bio or '',
            experience_years=user.experience_years,
            daily_wage=user.daily_wage,
            rating=user.rating,
            review_count=user.review_count,
            jobs_done=user.jobs_done,
            is_verified=user.is_verified,
            accepts_jobs=user.accepts_jobs,
            created_by_id=admin_map.get(user.created_by_id),
        )
        provider.services.set(user.services.values_list('pk', flat=True))
        provider.cities.set(user.cities.values_list('pk', flat=True))

    for booking in Booking.objects.exclude(confirmed_by_id=None):
        account_id = admin_map.get(booking.confirmed_by_id)
        if account_id:
            booking.confirmed_by_admin_id = account_id
            booking.save(update_fields=['confirmed_by_admin_id'])

    User.objects.filter(pk__in=admin_map).delete()


